import{z as E,x as i,o,c,q as t,j as s,D as e,d as l,s as n,S as d}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"借用检查","description":"","frontmatter":{"title":"借用检查","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/borrow-checker.md","filePath":"cs/borrow-checker.md","lastUpdated":1791413859000}'),p={name:"cs/borrow-checker.md"};function A(m,a,B,h,u,_){const r=i("Mermaid");return o(),c("div",null,[a[2]||(a[2]=t('<h1 id="借用检查" tabindex="-1">借用检查 <a class="header-anchor" href="#借用检查" aria-label="Permalink to &quot;借用检查&quot;">​</a></h1><div class="epigraph"><p>在唯一所有权之上，允许临时共享：同一时刻要么多个只读借用，要么一个可变借用。检查的是别名纪律，不是运行时锁。</p><footer>—— 据 Rust 所有权与借用规则（Matsakis 等）；Grossman 等 Cyclone；对照 Reynolds 干扰控制整理</footer></div><p>上一课<a href="/cs/linear-ownership">线性与所有权</a>禁止别名。实用程序要只读共享与短暂可变。缺口是<strong>借用</strong>：<code>&amp;T</code> / <code>&amp;mut T</code> 不转移所有权，但限制拥有者在借用期间的使用。本课钉互斥规则与「冻结」，不把区域推断写完——下一课生命周期。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若允许 <code>&amp;mut</code> 与 <code>&amp;</code> 同时存在，只读方看见的值可被改，或两个 <code>&amp;mut</code> 数据竞争。规则：活跃借用集合里，可变与任何其它借用互斥。缺口是<strong>静态别名集</strong>，不是<a href="/cs/alias-analysis">别名分析</a>那种中端优化（后者保守允许「可能别名」；借用检查失败则拒绝程序）。</p><p>NLL（non-lexical lifetimes）把活跃区间从作用域缩到最后一次使用。这是检查精度，不是新语义。</p><h3 id="借用不是-gc-根" tabindex="-1">借用不是 GC 根 <a class="header-anchor" href="#借用不是-gc-根" aria-label="Permalink to &quot;借用不是 GC 根&quot;">​</a></h3><p>借用不延长堆对象到「程序结束」；它要求对象已有拥有者活着。悬空借用由生命周期拒绝，下一课。本课先钉同一函数内的冲突。</p><p><span class="marginnote">Cyclone 是 Rust 之前的安全 C 方言。Rust RFC 与 NLL 设计是工程来源。本课不引用虚构 arXiv。Appel 的安全讨论可对照，但不把 Rust 写进 Appel 原书。</span></p><p><span class="marginnote">术语翻译：<strong>所有权</strong>=「谁负责释放这块内存」；<strong>借用</strong>=「临时借来看看或改改，不接手释放责任」。就像借书：图书馆（拥有者）把书借给你（借用者），书丢了还是图书馆的账。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对每个位置维护：拥有者是否被移走、只读借用计数、是否有可变借用。赋值、<code>&amp;mut</code> 再借用、分裂借用（字段不重叠）是精细规则。失败：诊断指出第一次借用与冲突使用。</p>',12)),(o(),s(d,null,{default:e(()=>[n(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20OWN%5B%22%E6%8B%A5%E6%9C%89%E8%80%85%22%5D%20--%3E%20SH%5B%22%E5%A4%9A%20%26%22%5D%0A%20%20OWN%20--%3E%20MU%5B%22%E4%B8%80%20%26mut%22%5D%0A%20%20SH%20-.-%3E%20X%5B%22%E4%BA%92%E6%96%A5%22%5D%0A%20%20MU%20-.-%3E%20X%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p>与<a href="/cs/let-polymorphism">值限制</a>：借用不引入 <code>ref</code> 多态那种洞，因为可变借用已钉死唯一写者。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>内部可变性（<code>Cell</code>/<code>RefCell</code>）把检查推迟到运行时或用 Unsafe 包起来。类型系统在安全子集里仍成立。不要用「全是 <code>unsafe</code>」当借用检查的定义。</p><p>内部字段借用：结构体拆借合法当字段不相交；这是静态形状，不是依值长度。</p><p>借用冲突如何判？检查器给每个值记三个数，沿着控制流逐句更新：</p>',5)),(o(),s(d,null,{default:e(()=>[n(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20S1%5B%22%E8%AF%AD%E5%8F%A5%EF%BC%9Alet%20mut%20v%22%5D%20--%3E%20S2%5B%22%E6%9B%B4%E6%96%B0%EF%BC%9A%E6%8B%A5%E6%9C%89%E8%80%85%E5%9C%A8%E3%80%81%E6%97%A0%E5%80%9F%E7%94%A8%22%5D%0A%20%20S2%20--%3E%20S3%5B%22%E8%AF%AD%E5%8F%A5%EF%BC%9Alet%20r1%20%3D%20%26v%22%5D%0A%20%20S3%20--%3E%20S4%5B%22%E6%9B%B4%E6%96%B0%EF%BC%9A%E5%8F%AA%E8%AF%BB%E5%80%9F%E7%94%A8%E6%95%B0%20%2B1%22%5D%0A%20%20S4%20--%3E%20Q%7B%22%E5%87%BA%E7%8E%B0%E5%86%99%E5%85%A5%E6%88%96%E6%96%B0%20%26mut%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E5%8F%AA%E8%AF%BB%E5%80%9F%E7%94%A8%E6%95%B0%200%22%7C%20OK%5B%22%E6%94%BE%E8%A1%8C%22%5D%0A%20%20Q%20--%3E%7C%22%E5%8F%AA%E8%AF%BB%E5%80%9F%E7%94%A8%E6%95%B0%201%22%7C%20ERR%5B%22%E7%BC%96%E8%AF%91%E9%94%99%E8%AF%AF%EF%BC%9A%E6%8C%87%E5%87%BA%E4%B8%A4%E6%AC%A1%E5%80%9F%E7%94%A8%E4%BD%8D%E7%BD%AE%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">常见误区：初学者以为借出后拥有者「失效」了。实际上拥有者还在，只是借用期间被<strong>冻结</strong>——不能改、不能移走。NLL 之后冻结范围更小：从最后一次使用借用处就解冻，不必等到作用域结束。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写跨函数的区域。后课默认：同时多读或一写。下一课生命周期与区域：借用能活多久、如何标进类型。</p><p>也不把 Python GIL 当借用检查。</p><p><span class="marginnote">数字实例：互斥规则只认两种合法状态——「只读借用 \\(\\ge 0\\) 个且可变借用 \\(=0\\)」或「可变借用 \\(=1\\) 且只读借用 \\(=0\\)」。\\(2\\) 个 <code>&amp;</code> 合法，\\(1\\) 个 <code>&amp;</code> 加 \\(1\\) 个 <code>&amp;mut</code> 不合法，\\(2\\) 个 <code>&amp;mut</code> 更不行。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>借用 = 不移动所有权的临时别名，带互斥。</li><li>检查拒绝，而不是插入锁。</li><li>NLL 按最后使用结束借用。</li><li>出处：Cyclone；Rust 借用规则；对照 Reynolds、Girard/Wadler 线性。</li></ul>',7))])}const F=E(p,[["render",A]]);export{f as __pageData,F as default};
